  [402000] = { "Power Word: Shieldのクールダウンを$N1秒短縮し、マナコストを$N2%軽減します。", nil, 0x91cc52b2, nil, "um" },
  [402004] = { "$D1の間、友好的な対象が受けるすべてのダメージを即座に$N1%軽減し、Dispelメカニクスへの耐性を$N2%上昇させます。", "受けるすべてのダメージが$N1%減少し、Dispelに対する耐性が$N2%上昇しています。", 0xf134f0eb, 0x2ab9e2e5, "uu" },
