  [402289] = { "$D2の間、$N2秒ごとに$N1回復します。", nil, 0xdcdbf572, nil, "um" },
  [402308] = { "Comprehension Charmで呪文のメモを解読し、新しいEngraving呪文を習得します。", nil, 0x7ccaad21, nil, "um" },
  [402311] = { "Comprehension Charmで呪文のメモを解読し、新しいEngraving呪文を習得します。", nil, 0x7ccaad21, nil, "um" },
  [402319] = { "Azora Apprentice Notesを$N1枚組み合わせて、新しいengravingのレシピを作ります。", nil, 0xd5254010, nil, "um" },
  [402362] = { nil, "与える回復量が$N1%増加します。", nil, 0xd76b0fc9, "mu" },
  [402368] = { nil, "与える呪文ダメージが$N1%増加します。", nil, 0xb9096e71, "mu" },
  [402668] = { "Vampiric Embraceのタレントを対象に適用し、$D1かけて対象に$N1のShadowダメージを与え、対象に与えたShadow呪文ダメージの$N3%に等しいマナをパーティメンバー全員に与えます。", "$N2秒ごとに$N1のShadowダメージを受けます。プリーストがこの目標に与えたShadow呪文ダメージの$N3%に等しいマナを、そのプリーストのパーティーが得ます。", 0x0fe3e73d, 0x3bf17666, "uu" },
  [402686] = { nil, "このクリーチャーは姿を変えられています。", nil, 0xf5cbc9b2, "mu" },
  [402779] = { "受けたShadow呪文ダメージの$N1%が、Priestのパーティーのマナを回復します。", nil, 0xf0e2b1af, nil, "um" },
  [402789] = { "$D1の間、虚空の目を呼び出して共に戦わせます。目は対象にさまざまな呪いをかけることができます。", nil, 0x305d9a60, nil, "um" },
  [402790] = { "敵に闇の魔法の矢を放ち、Shadowダメージを与えます。", nil, 0x42ce8448, nil, "um" },
  [402791] = { "$D1の間対象に呪いをかけ、ShadowとArcaneの耐性を$N2低下させ、受けるShadowとArcaneのダメージを$N3%増加させます。一体の対象にかけられるCurseは、ウォーロック一人につき一つだけです。", "ShadowとArcaneの耐性が$N1低下します。受けるShadowとArcaneのダメージが$N2%増加します。", 0xd622ece7, 0xa6c9f31f, "uu" },
  [402792] = { "$D1の間対象に呪いをかけ、FireとFrostの耐性を$N2低下させ、受けるFireとFrostのダメージを$N3%増加させます。一体の対象にかけられるCurseは、ウォーロック一人につき一つだけです。", "FireとFrostの耐性が$N1低下します。受けるFireとFrostのダメージが$N2%増加します。", 0xfe48135a, 0x4abb0038, "uu" },
  [402794] = { "対象にDemonicで話させ、すべての呪文の詠唱時間を$N1%遅くします。一体の対象にかけられるCurseは、ウォーロック一人につき一つだけです。$D1持続します。", "Demonicを話しているため、詠唱時間が$N1%増加します。", 0x26665dfe, 0xa89ef244, "uu" },
  [402799] = { "自らの魂の欠片を割り取り、自分の小さな分身を$N1体動かします。分身はメイス、剣、斧で現在の対象を攻撃し、命中した対象の攻撃速度、攻撃力、アーマーをそれぞれ低下させます。", nil, 0x15c256c1, nil, "um" },
  [402801] = { "スケルトンを$N1体動かし、メイス、剣、斧で現在の対象を攻撃させます。それぞれ対象の攻撃速度、攻撃力、アーマーを低下させます。", nil, 0xf7b13019, nil, "um" },
  [402802] = { "スケルトンを$N1体動かし、メイス、剣、斧で現在の対象を攻撃させます。それぞれ対象の攻撃速度、攻撃力、アーマーを低下させます。", nil, 0xf7b13019, nil, "um" },
  [402808] = { "敵の攻撃間隔を$N1%延ばします。$D1持続します。", "攻撃間隔が$N1%長くなっています。", 0x2c4ab1cd, 0x4f44ab25, "uu" },
  [402811] = { "対象のAttack Powerを$N1低下させます。$D1持続します。", "Attack Powerが$N1減少します。", 0x915e951a, 0xe8e28594, "uu" },
  [402818] = { "敵のアーマーを$N1低下させます。$D1持続します。", "アーマーが$N1低下しています。", 0x332347c0, 0x57b604c7, "uu" },
  [402832] = { "Prayer of Mendingのアビリティを得ます：\n\n$I1\n対象に呪文をかけ、次にダメージを受けるか非周期の治癒を受けたときに対象を$N1回復させます。回復が発生すると、Prayer of Mendingは$N2ヤード以内のパーティーまたはレイドのメンバーに飛び移ります。最大$N3回まで飛び移り、飛び移るたびに$D1持続します。この呪文は術者1人につき一度に一つの対象にしかかけられません。", nil, 0x90fb0eff, nil, "um" },
  [402833] = { "Shadow Word: Deathのアビリティを得ます：\n\n$I1\n闇の束縛の言葉で、対象に$N1のShadowダメージを与えます。Shadow Word: Deathで対象を倒せなかった場合、術者は対象に試みたダメージの$N2%に等しいダメージを受けます。", nil, 0x45a66e95, nil, "um" },
  [402834] = { "Soul Wardingのアビリティを得ます：\n\n$I1\nPower Word: Shieldの呪文のクールダウンを$D1短縮し、マナコストを$N2%減少させます。", nil, 0x51131f6a, nil, "um" },
  [402836] = { "Homunculiのアビリティを得ます：\n\n$I1\n自分の魂の欠片を割り、自分の小さな分身を$N1体動かします。分身はメイス、剣、斧で現在の対象を攻撃しようとし、攻撃を当てた対象の攻撃速度、攻撃力、アーマーをそれぞれ低下させます。", nil, 0xb55934a5, nil, "um" },
  [402837] = { "Binding Healのアビリティを得ます：\n\n$I1\n味方の対象と術者の体力を$N1回復します。脅威は低めです。", nil, 0xcfddc68b, nil, "um" },
  [402838] = { "Shared Painのアビリティを得ます：\n\n$I1\nShadow Word: Painが、$N2ヤード以内の近くにいる追加の対象最大$N1体にも効果を及ぼすようになります。", nil, 0x0264c853, nil, "um" },
  [402839] = { "Pain Suppressionのアビリティを得ます：\n\n$I1\n$D1の間、味方の対象が受けるすべてのダメージを即座に$N1%減少させ、Dispelへの耐性を$N2%上昇させます。", nil, 0xb5d5e294, nil, "um" },
  [402841] = { "Vampiric Touchのアビリティを得ます：\n\n$I1\n対象にVampiric Embraceの才能を適用し、$D1かけて対象に$N1のShadowダメージを与え、対象に与えたShadow呪文ダメージの$N3%に等しいマナをすべてのパーティーメンバーが得ます。", nil, 0x4079090c, nil, "um" },
  [402842] = { "Circle of Healingのアビリティを得ます：\n\n$I1\n対象のプレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティーメンバー全員の体力を$N2回復します。", nil, 0x0e8241db, nil, "um" },
  [402843] = { "Shadowfiendのアビリティを得ます：\n\n$I1\n影の悪鬼を生み出して対象を攻撃させます。Shadowfiendが攻撃すると、術者はマナを$N1%得ます。$D1持続します。", nil, 0x893e0778, nil, "um" },
