  [402846] = { "Eye of the Voidのアビリティを得ます：\n\n$I1\n$D1の間、自分のために戦う虚無の目を呼び出します。目は対象にさまざまな呪いをかけることができます。", nil, 0xf311e4df, nil, "um" },
  [402848] = { "脚部にPrayer of Mendingのルーンを刻みます：\n\n$I1\n対象に呪文をかけ、次にダメージを受けるか非周期の治療を受けたときに$N1回復させます。回復が起こると、Prayer of Mendingは$N2ヤード以内のパーティーまたはレイドのメンバーに移ります。最大$N3回移り、移るたびに$D1持続します。この呪文は術者ごとに同時に一体の対象にしかかけられません。", nil, 0x2bda4bfd, nil, "um" },
  [402849] = { "手袋にShadow Word: Deathのルーンを刻みます：\n\n$I1\n闇の束縛の言葉で、対象に$N1のShadowダメージを与えます。対象がShadow Word: Deathで倒れなかった場合、術者は対象に与えようとしたダメージの$N2%に等しいダメージを受けます。", nil, 0x139a0879, nil, "um" },
  [402850] = { "外套にSoul Wardingのルーンを刻みます：\n\n$I1\nPower Word: Shieldのクールダウンを$D1短縮し、マナ消費を$N2%減らします。", nil, 0x154e3993, nil, "um" },
