  [402853] = { "外套にBinding Healのルーンを刻みます：\n\n$I1\n味方の対象と術者を$N1回復します。脅威は低いです。", nil, 0x992a730c, nil, "um" },
  [402854] = { "脚部にShared Painのルーンを刻みます：\n\n$I1\nShadow Word: Painが、$N2ヤード以内の近くの対象最大$N1体にも効果を及ぼすようになります。", nil, 0xd899d8ce, nil, "um" },
  [402855] = { "ブーツにPain Suppressionのルーンを刻みます：\n\n$I1\n$D1の間、味方の対象が受けるすべてのダメージを即座に$N1%減少させ、Dispel効果への耐性を$N2%上昇させます。", nil, 0xb2fd4d86, nil, "um" },
